import json, math, random, sys, time, os
from functools import lru_cache

name=sys.argv[1]; seconds=float(sys.argv[2]) if len(sys.argv)>2 else 30
O=json.load(open('/app/orders/'+name+'.json')); C={c['id']:c for c in O['customers']}; D=O['depot']; F={f['type']:f for f in O['fleet']}; TYPES=list(F)
ids=list(C); rnd=random.Random(41731+len(ids)); target=json.load(open('/app/orders/targets.json'))[name]
def dist(a,b): return math.ceil(math.hypot(a['x']-b['x'],a['y']-b['y']))
DM={(a,b):dist(D if a==0 else C[a],D if b==0 else C[b]) for a in [0]+ids for b in [0]+ids}

@lru_cache(maxsize=1000000)
def ev(t, s):
 f=F[t]; s=list(s)
 if not s:return None
 load=sum(C[i]['demand'] for i in s)
 if load>f['capacity']: return None
 dd=DM[0,s[0]]+sum(DM[a,b] for a,b in zip(s,s[1:]))+DM[s[-1],0]
 if f['range'] is not None and dd>f['range']: return None
 # latest departure satisfying all due times and depot close
 latest=D['close']-DM[s[-1],0]*f['pace']
 for k in range(len(s)-1,-1,-1):
  c=C[s[k]]; start=min(c['due'],latest-c['service'])
  if start<c['ready']: return None
  latest=start-DM[0 if k==0 else s[k-1],s[k]]*f['pace']
 dep=latest
 if dep<D['open']: return None
 # forward validation and shift
 clock=dep; prev=0
 for i in s:
  clock=max(clock+DM[prev,i]*f['pace'],C[i]['ready'])
  if clock>C[i]['due']:return None
  clock+=C[i]['service']; prev=i
 back=clock+DM[prev,0]*f['pace']
 if back>D['close'] or back-dep>f['shift']: return None
 return f['fixed']+f['per_unit']*dd, dep, dd

def cost(sol): return sum(ev(t,tuple(s))[0] for t,s in sol)
def counts(sol):
 z={t:0 for t in TYPES}
 for t,s in sol:z[t]+=1
 return z

def options(sol,cid,noise=0.0, limit=999999):
 out=[]
 for r,(t,s) in enumerate(sol):
  old=ev(t,tuple(s))[0]
  for p in range(len(s)+1):
   ns=tuple(s[:p]+[cid]+s[p:]); e=ev(t,ns)
   if e: out.append((e[0]-old+rnd.random()*noise,r,p,t,ns,e[0]-old))
 cnt=counts(sol)
 for t in TYPES:
  if cnt[t]<F[t]['count']:
   e=ev(t,(cid,))
   if e:out.append((e[0]+rnd.random()*noise,len(sol),0,t,(cid,),e[0]))
 out.sort(key=lambda x:x[0])
 return out[:limit]

def insert(sol, un, noisy=0, regret=True):
 un=set(un)
 while un:
  choices=[]
  sample=list(un) if len(un)<45 else rnd.sample(list(un),45)
  for c in sample:
   op=options(sol,c,noisy,3)
   if op:
    reg=(op[1][0]-op[0][0] if len(op)>1 else 20000)
    # prioritize constrained customers; mild urgency/demand tie-break
    score=reg + C[c]['demand']*8 if regret else -op[0][0]
    choices.append((score,c,op[0]))
  if not choices:return None
  _,c,x=max(choices)
  _,r,p,t,ns,_=x
  if r==len(sol):sol.append((t,list(ns)))
  else:sol[r]=(t,list(ns))
  un.remove(c)
 return sol

def initial():
 # hardest first through regret insertion; seed mandatory large-demand customers
 sol=[]
 order=sorted(ids,key=lambda i:(C[i]['demand']>60, C[i]['demand'], -C[i]['due']),reverse=True)
 return insert(sol,order,0,True)

def retype(sol):
 # greedily accept individual type changes, then pair swaps
 changed=True
 while changed:
  changed=False; cnt=counts(sol)
  for r,(t,s) in enumerate(sol):
   old=ev(t,tuple(s))[0]
   for nt in TYPES:
    if nt==t or cnt[nt]>=F[nt]['count']:continue
    e=ev(nt,tuple(s))
    if e and e[0]<old:
     sol[r]=(nt,s);cnt[t]-=1;cnt[nt]+=1;changed=True;break
 return sol

def improve_routes(sol):
 # route reversal and random intra-route 2-opt
 for r,(t,s) in enumerate(sol):
  base=ev(t,tuple(s))[0]; cand=list(reversed(s)); e=ev(t,tuple(cand))
  if e and e[0]<base:sol[r]=(t,cand);base=e[0];s=cand
  for _ in range(min(30,len(s)*3)):
   if len(s)<3:break
   a,b=sorted(rnd.sample(range(len(s)+1),2))
   if b-a<2:continue
   ns=s[:a]+list(reversed(s[a:b]))+s[b:]; e=ev(t,tuple(ns))
   if e and e[0]<base:s=ns;base=e[0];sol[r]=(t,s)
 return sol

start=time.time(); best=None; bestc=10**18
# Several construction attempts
for z in range(12):
 sol=initial()
 if sol:
  sol=retype(improve_routes(sol)); cc=cost(sol)
  if cc<bestc:best=[(t,s[:]) for t,s in sol];bestc=cc;print('initial',z,bestc,len(best),flush=True)
 if time.time()-start>seconds*.2:break
if best is None: raise SystemExit('could not construct')
cur=[(t,s[:]) for t,s in best]; curc=bestc; it=0
while time.time()-start<seconds and bestc>target:
 it+=1; cand=[(t,s[:]) for t,s in cur]
 # related/random destroy
 q=rnd.randint(max(3,len(ids)//25),max(5,len(ids)//9))
 if rnd.random()<.65:
  seed=rnd.choice(ids); pool=sorted(ids,key=lambda i:DM[seed,i]+abs(C[seed]['ready']-C[i]['ready'])/30)
  rem=set(pool[:q])
 else: rem=set(rnd.sample(ids,q))
 ns=[]
 for t,s in cand:
  x=[i for i in s if i not in rem]
  if x:ns.append((t,x))
 cand=insert(ns,rem,noise=300+rnd.random()*1800,regret=rnd.random()<.8)
 if not cand:continue
 if rnd.random()<.35:cand=retype(cand)
 if rnd.random()<.25:cand=improve_routes(cand)
 cc=cost(cand)
 temp=max(40,1000*(1-(time.time()-start)/seconds))
 if cc<curc or rnd.random()<math.exp((curc-cc)/temp):cur,curc=cand,cc
 if cc<bestc:
  best=[(t,s[:]) for t,s in cand];bestc=cc
  print('best',it,bestc,'routes',len(best),'counts',counts(best),flush=True)
# final departure values
routes=[]
for t,s in best:
 e=ev(t,tuple(s)); routes.append({'type':t,'depart':int(e[1]),'stops':s})
os.makedirs('/app/plans',exist_ok=True)
json.dump({'routes':routes},open('/app/plans/'+name+'.json','w'),indent=2)
print('FINAL',name,bestc,'target',target,'iterations',it,'cache',ev.cache_info())
